// Command openapi writes the OpenAPI document generated by the HTTP package.
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/the9thphoto/MicroclimateMonitoring-Server/apps/api/internal/httpapi"
)

func main() {
	_, api := httpapi.New(nil, nil, httpapi.Options{
		AppName: "Campus Weather Monitor API",
	})

	encoder := json.NewEncoder(os.Stdout)
	encoder.SetEscapeHTML(false)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(api.OpenAPI()); err != nil {
		fmt.Fprintln(os.Stderr, "encode OpenAPI document:", err)
		os.Exit(1)
	}
}
